import{z as s,x as A,o as e,c as p,q as n,j as i,D as E,d as o,s as B,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Eaton–Kortum","description":"","frontmatter":{"title":"Eaton–Kortum","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/eaton-kortum.md","filePath":"econ/eaton-kortum.md","lastUpdated":1791063341000}'),m={name:"econ/eaton-kortum.md"};function d(D,a,u,h,C,c){const r=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=n('<h1 id="eaton–kortum" tabindex="-1">Eaton–Kortum <a class="header-anchor" href="#eaton–kortum" aria-label="Permalink to &quot;Eaton–Kortum&quot;">​</a></h1><div class="epigraph"><p>每个品种的最低成本供应国由极值生产率抽签决定；加总之后份额是闭式引力，贸易弹性来自生产率分布的形状，而不是另设一个 CES 进口需求。</p><footer>—— Eaton and Kortum, Technology, Geography, and Trade, Econometrica 2002</footer></div><p><a href="/econ/gravity-model">上一课</a>把引力写成 CES 加总。本课给出李嘉图微观基础：Eaton–Kortum（EK）。关税下一课把 \\(\\tau\\) 写成政策。本课钉：Frechet 生产率、进口份额、与 Melitz 的分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连续品种，国 \\(i\\) 在品种 \\(\\omega\\) 上的生产率抽自 Frechet。买者在各国报价（含冰山）里选最便宜。极值性质：国 \\(i\\) 占 \\(j\\) 进口的份额只依赖相对成本与贸易成本，形式与引力相同；形状参数 \\(\\theta\\) 是贸易弹性——\\(\\theta\\) 大则生产率差小，贸易对成本极敏感。缺口不是再估一条距离回归，而是：李嘉图比较成本在连续品种上被随机化，仍长出可计算的多国一般均衡。DFS 连续商品是祖先；EK 把它放到多国地理里。</p><p><span class="marginnote">\\(\\theta\\) 可从双边贸易对成本的反应估，也可从国内生产份额。识别争论存在，但对象清楚：它是技术离散程度，不是偏好 \\(\\sigma\\) 的另一个名字——尽管观测上常纠缠。</span></p><p><span class="marginnote">Frechet 抽签的含义：各国在每个品种上的生产率像抽奖，手气有肥有瘦。EK 的数学运气在于，『从各国抽签中取最小成本』的结果仍属于同一族分布——所以加总后的进口份额才有干净的闭式公式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成本 \\(c_i\\tau_{ij}/z_i(\\omega)\\)。Frechet 使 \\(\\min\\) 仍 Frechet。支出份额 \\(\\pi_{ij}\\propto (c_i\\tau_{ij})^{-\\theta}\\)。商品市场出清定工资。反事实：改关税或技术，用帽子代数解新 \\(\\pi\\) 与福利（消费价格指数含进口品种）。与 Melitz：EK 是完全竞争李嘉图（每种品种最低成本一国供应），Melitz 是垄断竞争选择；两者都可以接引力，福利分解不同（再配置 vs 比较成本抽签）。</p><p><span class="marginnote">数字实例：取 \\(\\theta=4\\)，甲国成本比乙国高 10%，则甲的份额约为乙的 \\(1.1^{-4}\\approx0.68\\) 倍；把 \\(\\theta\\) 换成 8，同样的成本差把份额压到约 0.47 倍。\\(\\theta\\) 越大，同样的成本差赶走的订单越多。</span></p>',10)),(e(),i(l,null,{default:E(()=>[B(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FR%5B%22Frechet%20z%22%5D%20--%3E%20MIN%5B%22%E5%90%84%E5%9B%BD%E6%9C%80%E4%BD%8E%E6%88%90%E6%9C%AC%E4%BE%9B%E5%BA%94%22%5D%0A%20%20MIN%20--%3E%20PI%5B%22%E4%BB%BD%E9%A2%9D%20%CF%80_ij%20%E9%97%AD%E5%BC%8F%22%5D%0A%20%20TH%5B%22%E5%BD%A2%E7%8A%B6%20%CE%B8%22%5D%20--%3E%20ELAST%5B%22%E8%B4%B8%E6%98%93%E5%BC%B9%E6%80%A7%22%5D%0A%20%20PI%20--%3E%20GE%5B%22%E5%B7%A5%E8%B5%84%E4%B8%8E%E7%A6%8F%E5%88%A9%E4%B8%80%E8%88%AC%E5%9D%87%E8%A1%A1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与计量结构：这是可计算的多国模型，矩是贸易份额与价格，不是 ATT。China shock 的简化式可以与 EK 反事实对照，但不是同一句话。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"机制是比较成本的随机化。每个品种仍是李嘉图：谁相对更擅长谁生产。地理 \\(\\tau\\) 决定「多擅长才值得跨越距离」。\\(\\theta\\) 小：各国技术差大，贸易增益大、弹性小。福利：进口就是间接使用外国技术；贸易成本下降等于技术扩散的一部分。",-1)),a[6]||(a[6]=t("p",null,"「一个品种的订单花落谁家」——从单笔到份额：",-1)),(e(),i(l,null,{default:E(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORD%5B%22%E6%9F%90%E5%93%81%E7%A7%8D%E7%9A%84%E4%B8%80%E7%AC%94%E8%AE%A2%E5%8D%95%22%5D%20--%3E%20COST%5B%22%E5%90%84%E5%9B%BD%E5%88%B0%E5%B2%B8%E6%88%90%E6%9C%AC%3A%20%E5%8D%95%E4%BD%8D%E6%88%90%E6%9C%AC%20%C3%97%20%E8%B4%B8%E6%98%93%E6%88%90%E6%9C%AC%22%5D%0A%20%20COST%20--%3E%20A%5B%22%E7%94%B2%E5%9B%BD%3A%20%E6%8A%80%E6%9C%AF%E6%8A%BD%E7%AD%BE%E5%A5%BD%2C%20%E5%88%B0%E5%B2%B8%209%20%E5%85%83%22%5D%0A%20%20COST%20--%3E%20B%5B%22%E4%B9%99%E5%9B%BD%3A%20%E5%B7%A5%E8%B5%84%E4%BD%8E%E4%BD%86%E6%8A%80%E6%9C%AF%E5%B7%AE%2C%20%E5%88%B0%E5%B2%B8%2012%20%E5%85%83%22%5D%0A%20%20COST%20--%3E%20C%5B%22%E4%B8%99%E5%9B%BD%3A%20%E8%B7%9D%E7%A6%BB%E8%BF%91%2C%20%E5%88%B0%E5%B2%B8%2011%20%E5%85%83%22%5D%0A%20%20A%20--%3E%20WIN%5B%22%E6%9C%80%E4%BD%8E%E8%80%85%E4%B8%AD%E6%A0%87%2C%20%E7%8B%AC%E5%AE%B6%E4%BE%9B%E8%B4%A7%22%5D%0A%20%20WIN%20--%3E%20AGG%5B%22%E5%85%A8%E9%83%A8%E5%93%81%E7%A7%8D%E5%8A%A0%E6%80%BB%3A%20%E4%BB%BD%E9%A2%9D%20%CF%80_ij%20%E6%88%90%E9%97%AD%E5%BC%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">θ 可类比『选手水平差多悬』。θ 大＝大家水平接近，一点成本差就换供应商，贸易对关税极其敏感；θ 小＝强弱悬殊，运费怎么涨活儿还是那几个能手干，贸易量对成本不敏感。</span></p><p>与 HO：EK 通常一种要素（劳动），分配薄。把投入产出、多种要素放进 EK（Caliendo–Parro）是延伸，本课最小模型是劳动 + 地理。</p><p><span class="marginnote">Alvarez–Lucas、Dekle–Eaton–Kortum 的帽子代数让反事实不必重新校准全部水平，只对变动求解——这是定量贸易的操作核。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 \\(\\theta\\) 的某个点估计写成自然常数。完全竞争使企业加成为零，与 Krugman/Melitz 的品种加成不同。下一课最优关税在大国 EK 或 CES 里都存在条款恶化动机。不要用 EK 取消产业内：加总份额看起来像引力，微观可以是品种内完全分工。</p><p>后课默认：多国李嘉图加 Frechet ⇒ 闭式引力，弹性是 \\(\\theta\\)。反事实用份额与帽子代数。Melitz 与 EK 是两条微观，不是互相否证。关税课把 \\(\\tau\\) 的政策部分拆出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EK：极值生产率 + 最低成本采购 ⇒ 闭式进口份额。</li><li>\\(\\theta\\) 是技术离散，也是贸易弹性。</li><li>定量反事实走帽子代数，不必重估全部水平。</li><li>与 Melitz：完全竞争比较成本 vs 垄断竞争选择。</li><li>出处：Eaton and Kortum, <em>Econometrica</em> 2002；Dornbusch–Fischer–Samuelson；Dekle–Eaton–Kortum。</li></ul>',8))])}const f=s(m,[["render",d]]);export{T as __pageData,f as default};
